// As in Adobe's sample: ./config.json is generated by `aio app build` / `aio app dev` and maps
// 'Package/action' to the deployed web action URL. The admin's IMS token and org go along with every call.
export async function callAction (props, action, body = {}) {
  const actions = require('./config.json')
  const res = await fetch(actions[action], {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-gw-ims-org-id': props.ims.org,
      authorization: `Bearer ${props.ims.token}`
    },
    body: JSON.stringify(body)
  })
  const data = await res.json()
  if (!res.ok) throw new Error((data && data.error) || `HTTP ${res.status}`)
  return data
}
